/**
 * The sitemap, built from the route table rather than kept alongside it.
 *
 * It used to be a committed `public/sitemap.xml` regenerated by a script, with
 * its own hand-written list of paths and a build-time check that the list still
 * matched the pages actually being built. Both the second list and the check
 * are gone: `ROUTES` comes from `guides.mjs`, which is also what puts the pages
 * on disk, so a guide cannot be announced without existing or exist without
 * being announced.
 *
 * Served at `/sitemap.xml` — the URL robots.txt points at and Search Console
 * already has — rather than the `sitemap-index.xml` an integration would give.
 *
 * The builder lives here, apart from the endpoint, so the tests can hold it to
 * the sitemaps.org schema without running a build.
 */
import { ROUTES, SITE_URL } from './guides.mjs';

/** YYYY-MM-DD, the W3C date form the sitemap spec asks for. */
export function isoDate(date = new Date()) {
  return date.toISOString().slice(0, 10);
}

/**
 * `lastmod` is the point of building this at deploy time rather than committing
 * a date by hand: a stale one is worse than none, because Google learns to
 * ignore it.
 */
export function buildSitemap(lastmod = isoDate()) {
  const urls = ROUTES.map(
    (route) =>
      `  <url>\n` +
      `    <loc>${SITE_URL}${route.path}</loc>\n` +
      `    <lastmod>${lastmod}</lastmod>\n` +
      `    <changefreq>${route.changefreq}</changefreq>\n` +
      `  </url>`
  ).join('\n');

  return (
    `<?xml version="1.0" encoding="UTF-8"?>\n` +
    `<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n` +
    `${urls}\n` +
    `</urlset>\n`
  );
}
